define("theme_chronolms/sidebar", ['jquery', 'core/str'], function($, Str) {
    'use strict';
    var SIDEBAR_KEY = 'clms_sidebar_collapsed';
    var sidebar = document.getElementById('chronolms-sidebar');
    var contentWrapper = document.getElementById('chronolms-content-wrapper');
    var toggleBtn = document.getElementById('sidebar-toggle-btn');
    var overlay = document.getElementById('sidebar-overlay');
    function isCollapsed() { return localStorage.getItem(SIDEBAR_KEY) === '1'; }
    function setCollapsed(collapsed) {
        if (!sidebar) return;
        if (collapsed) {
            sidebar.classList.add('collapsed');
            if (contentWrapper) contentWrapper.classList.add('sidebar-collapsed');
            localStorage.setItem(SIDEBAR_KEY, '1');
            if (toggleBtn) toggleBtn.setAttribute('aria-expanded', 'false');
        } else {
            sidebar.classList.remove('collapsed');
            if (contentWrapper) contentWrapper.classList.remove('sidebar-collapsed');
            localStorage.removeItem(SIDEBAR_KEY);
            if (toggleBtn) toggleBtn.setAttribute('aria-expanded', 'true');
        }
    }
    function isMobile() { return window.innerWidth <= 640; }
    function initSidebar() {
        if (!sidebar) return;
        if (!isMobile() && isCollapsed()) setCollapsed(true);
        if (toggleBtn) {
            toggleBtn.addEventListener('click', function() {
                if (isMobile()) {
                    sidebar.classList.toggle('open');
                    if (overlay) overlay.classList.toggle('visible');
                } else {
                    setCollapsed(!sidebar.classList.contains('collapsed'));
                }
            });
        }
        if (overlay) {
            overlay.addEventListener('click', function() {
                sidebar.classList.remove('open');
                overlay.classList.remove('visible');
            });
        }
    }
    return { init: function() { initSidebar(); } };
});
